#include <Wire.h>
void nibble(byte n,bool rs){Wire.beginTransmission(0x27);Wire.write((n<<4)|8|(rs?1:0)|4);Wire.endTransmission();delayMicroseconds(10);Wire.beginTransmission(0x27);Wire.write((n<<4)|8|(rs?1:0));Wire.endTransmission();delayMicroseconds(100);}
void send(byte v,bool rs){nibble(v>>4,rs);nibble(v&15,rs);}
void setup(){Wire.begin();delay(50);nibble(3,false);delay(5);nibble(3,false);nibble(3,false);nibble(2,false);send(0x28,false);send(1,false);delay(2);send(0x0C,false);const char* text="Privet";while(*text)send(*text++,true);}
